{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table snitch_db.maplemonk.CHANNELS_TARGET_ANALYTICS as with Base_Data AS ( SELECT L_1_CATEGORY AS L1_category, CASE WHEN LOWER(TRIM(category)) = \'tshirts\' THEN \'T-shirts\' ELSE category END AS category, CHANNELS, TRY_TO_NUMBER(REPLACE(qty, \',\', \'\')) AS qty, gm_ AS gross_margin, month, COALESCE( TRY_TO_DATE(TRIM(month), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(month) || \'-01\', \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(month), \'MON-YY\'), TRY_TO_DATE(TRIM(month), \'MONTH-YY\') ) AS month_date FROM snitch_db.maplemonk.channels_target ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category, MAX(cogs) AS sku_cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), sales_QTY AS ( SELECT m.l1_category, CASE WHEN LOWER(TRIM(m.category)) = \'tshirts\' THEN \'T-shirts\' ELSE m.category END AS category, CASE WHEN UPPER(TRIM(h.type)) = \'STORE\' THEN \'Offline\' WHEN UPPER(TRIM(h.type)) = \'MARKETPLACE\' THEN \'MP\' ELSE \'Shopify\' END AS channels, SUM(h.gross_quantity) AS sales_qty, SUM(h.gross_sales) AS gross_sales, SUM(h.gross_quantity * COALESCE(m.sku_cogs,0)) AS cogs FROM snitch_db.maplemonk.horizontal_sales_categories h LEFT JOIN meta_map m ON UPPER( IFF( UPPER(REPLACE(h.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(h.sku_group, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(h.sku_group, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(h.sku_group, \' \', \'\'), \'-.*$\', \'\') ) ) = m.sku_group_clean WHERE h.date >= \'2026-04-01\' GROUP BY 1,2,3 ), final AS ( SELECT b.L1_category, b.category, b.qty AS target_qty, b.gross_margin AS GM_target, b.month, b.channels, COALESCE(s.sales_qty,0) AS sales_qty, COALESCE(s.gross_sales,0) AS gross_sales, b.qty - COALESCE(s.sales_qty,0) AS Remaining_target, COALESCE( ROUND( ((b.qty - COALESCE(s.sales_qty,0)) / NULLIF(b.qty,0)) * 100 ), 0) AS pct_remaining_qty, COALESCE(s.cogs,0) AS cogs, ROUND( (1 - (COALESCE(s.cogs,0) / NULLIF(COALESCE(s.gross_sales,0),0))) * 100 ,2) AS gross_margin, ROUND( TRY_TO_NUMBER(REPLACE(b.gross_margin, \'%\', \'\')) * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())) , 2) AS target_gm_till_date FROM Base_Data b LEFT JOIN sales_QTY s ON UPPER(TRIM(b.L1_category)) = UPPER(TRIM(s.L1_category)) AND UPPER(TRIM(b.category)) = UPPER(TRIM(s.category)) AND UPPER(TRIM(b.channels)) = UPPER(TRIM(s.channels)) ) SELECT * FROM final;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            